const remoteJobs = remoteResponse.length ? remoteResponse[0].jobs || [] : [];
const nowIso = new Date().toISOString();
const nowMs = Date.now();
const MAX_HISTORICO = 400;
const sourceNames = ['Frontend BR', 'Backend BR', 'Himalayas'];
function safeArray(value) {
