}
const previous = JSON.parse(Buffer.from(githubFile.content.replace(/\s/g, ''), 'base64').toString('utf8'));
const current = Array.isArray(previous.vagas) ? previous.vagas : [];
const ultimaConsultaBemSucedida = {};
let successCount = 0;
for (const name of sourceNames) {
  const items = Array.isArray(sourceState[name]) ? sourceState[name] : [];
  if (items !== undefined && Array.isArray(sourceState[name])) {
    ultimaConsultaBemSucedida[name] = nowIso;
    successCount += 1;
  }
}
const allSourcesFailed = successCount === 0;
if (allSourcesFailed) {
  const payload = {
    atualizadoEm: previous.atualizadoEm || nowIso,
    total: current.length,
    vagas: current,
    ultimaSincronizacao: nowIso,
    ultimaSincronizacaoCompleta: previous.ultimaSincronizacaoCompleta || null,
    ultimaSincronizacaoParcial: previous.ultimaSincronizacaoParcial || null,
    ultimaConsultaBemSucedida: { ...(previous.ultimaConsultaBemSucedida || {}), ...ultimaConsultaBemSucedida },
    limiteHistorico: MAX_HISTORICO,
    novasNaExecucao: 0,
    historicoPreservado: true,
    statusExecucao: 'historico_preservado_sem_fonte_ativa'
  };
  return [{ json: { changed: false, total: current.length, novos: 0, status: 'historico_preservado', sha: githubFile.sha, content: Buffer.from(JSON.stringify(payload, null, 2) + '\n', 'utf8').toString('base64') } }];
}
function textValue(v) {
  return String(v ?? '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
}
function isoDate(value) {
  if (!value) return '';
  const numeric = Number(value);
  const parsed = new Date(Number.isFinite(numeric) && numeric > 100000000 ? numeric * 1000 : value);
  return Number.isNaN(parsed.getTime()) ? '' : parsed.toISOString();
}
function ensureDate(value, fallback) {
  if (!value) return fallback;
  return value;
}
const reDev = /desenvolv|developer|programador|programming|engenheir[oa] de software|software engineer|front.?end|back.?end|full.?stack|python|javascript|typescript|react|node\.?js|qa|testes|quality assurance|est[aá]gio.*(ti|tecnologia|sistemas)/i;
const reEntry = /\b(junior|júnior|jr\.?|est[aá]gio|estagi[aá]ri[oa]|intern(ship)?|trainee|entry[ -]?level|sem experi[eê]ncia|primeiro emprego|aprendiz)\b/i;
const reSenior = /\b(senior|s[eê]nior|sr\.?|lead|principal|staff|manager|gerente|arquiteto|architect|pleno|mid[ -]?level)\b/i;
function fromIssues(items, sourceName) {
  return (Array.isArray(items) ? items : []).flatMap(v => {
    if (!v || !v.id || v.pull_request || v.state !== 'open') return [];
    const labels = Array.isArray(v.labels) ? v.labels.map(l => l.name || '').join(' ') : '';
    const title = String(v.title || '');
    const description = textValue(v.body || '');
    if (!reDev.test(title + ' ' + labels + ' ' + description.slice(0, 700))) return [];
    if (!reEntry.test(title + ' ' + labels + ' ' + description.slice(0, 2000)) || reSenior.test(title + ' ' + labels)) return [];
    const publishedEm = isoDate(v.created_at);
