    const empType = String(v.employmentType || '');
    if (!reDev.test(title) || reSenior.test(title)) return [];
    if (!(reEntry.test(title + ' ' + seniority + ' ' + empType) || /entry[ -]?level/i.test(seniority))) return [];
    if (!v.guid || !v.applicationLink) return [];
    const location = Array.isArray(v.locationRestrictions) ? v.locationRestrictions : [];
    if (location.length && !location.some(c => /brazil|brasil|^br$/i.test(typeof c === 'string' ? c : (c.name || c.code || '')))) return [];
    return [{
      id: 'himalayas-' + v.guid,
      cargo: title,
      empresa: v.companyName || 'Não informada',
      nivel: /est[aá]gio|intern|aprendiz|trainee/i.test(title + ' ' + seniority + ' ' + empType) ? 'Estágio' : 'Júnior',
      modalidade: 'Remoto',
      local: location.length ? 'Brasil' : 'Mundial (ver restrições)',
      descricao: textValue(v.excerpt || v.description).slice(0, 450),
      publicadoEm: isoDate(v.pubDate),
      expiraEm: isoDate(v.expiryDate),
      fonte: 'Himalayas',
      link: v.applicationLink,
      capturadoEm: nowIso
    }];
  });
}
const incoming = [
  ...fromIssues(sourceState['Frontend BR'], 'Frontend BR'),
  ...fromIssues(sourceState['Backend BR'], 'Backend BR'),
  ...fromHimalayas(sourceState['Himalayas'])
];
const byId = new Map((Array.isArray(current) ? current : []).map(v => [v.id, v]));
const seenIds = new Set();
const merged = new Map();
for (const item of current) {
  if (item && item.id) {
    item.primeiraIdentificacao = item.primeiraIdentificacao || item.ultimaIdentificacao || item.capturadoEm || nowIso;
    item.ultimaIdentificacao = item.ultimaIdentificacao || item.primeiraIdentificacao || item.capturadoEm || nowIso;
    item.statusIdentificacao = item.statusIdentificacao || 'existente';
    merged.set(item.id, item);
  }
}
let novasNaExecucao = 0;
for (const item of incoming) {
  const currentItem = merged.get(item.id);
  const incomingCopy = { ...item };
  if (!incomingCopy.publicadoEm && item.publicadoEm) incomingCopy.publicadoEm = item.publicadoEm;
  if (currentItem) {
    incomingCopy.primeiraIdentificacao = currentItem.primeiraIdentificacao || incomingCopy.primeiraIdentificacao || incomingCopy.capturadoEm || nowIso;
    incomingCopy.ultimaIdentificacao = nowIso;
    incomingCopy.publicadoEm = ensureDate(currentItem.publicadoEm || incomingCopy.publicadoEm, incomingCopy.publicadoEm);
    incomingCopy.statusIdentificacao = (currentItem.primeiraIdentificacao && currentItem.primeiraIdentificacao !== currentItem.ultimaIdentificacao) ? 'anteriormente-identificada' : 'existente';
    incomingCopy.ultimaConsultaBemSucedida = currentItem.ultimaConsultaBemSucedida || { ...currentItem.ultimaConsultaBemSucedida };
    const finalItem = { ...currentItem, ...incomingCopy };
    finalItem.publicadoEm = finalItem.publicadoEm || incomingCopy.publicadoEm;
    finalItem.primeiraIdentificacao = finalItem.primeiraIdentificacao || nowIso;
    finalItem.ultimaIdentificacao = nowIso;
    if (!finalItem.capturadoEm) finalItem.capturadoEm = nowIso;
    merged.set(item.id, finalItem);
  } else {
    incomingCopy.primeiraIdentificacao = incomingCopy.primeiraIdentificacao || nowIso;
    incomingCopy.ultimaIdentificacao = nowIso;
    incomingCopy.statusIdentificacao = 'nova';
    incomingCopy.ultimaConsultaBemSucedida = { ...ultimaConsultaBemSucedida };
    merged.set(item.id, incomingCopy);
    novasNaExecucao += 1;
  }
  seenIds.add(item.id);
}
let vagas = Array.from(merged.values()).sort((a, b) => {
