  const bDate = b.ultimaIdentificacao || b.publicadoEm || b.capturadoEm || '';
  return new Date(bDate || 0).getTime() - new Date(aDate || 0).getTime();
}).slice(0, MAX_HISTORICO);
for (const vaga of vagas) {
