  vaga.ultimaIdentificacao = vaga.ultimaIdentificacao || vaga.primeiraIdentificacao || nowIso;
  vaga.statusIdentificacao = vaga.statusIdentificacao || 'existente';
  vaga.publicadoEm = vaga.publicadoEm || vaga.capturadoEm || null;
