  ultimaSincronizacao: nowIso,
  ultimaSincronizacaoCompleta: successCount === sourceNames.length ? nowIso : (previous.ultimaSincronizacaoCompleta || null),
  ultimaSincronizacaoParcial: successCount > 0 && successCount < sourceNames.length ? nowIso : (previous.ultimaSincronizacaoParcial || null),
